@pytest.mark.parametrize('orientation', ['vertical', 'horizontal'])
@pytest.mark.parametrize('explicit_bins', [False, True])
def test_hist_float16_bar_edges(orientation, explicit_bins):
    data = np.linspace(0, 1, 1000, dtype=np.float16)
    bins = np.linspace(0, 1, 101, dtype=np.float16) if explicit_bins else 100
    expected_counts, expected_edges = np.histogram(data, bins=bins)
    _, ax = plt.subplots()
    counts, edges, patches = ax.hist(
        data, bins=bins, orientation=orientation, alpha=0.5)

    assert_array_equal(counts, expected_counts)
    assert_array_equal(edges, expected_edges)
    if orientation == 'vertical':
        left = np.array([patch.get_x() for patch in patches])
        width = np.array([patch.get_width() for patch in patches])
    else:
        left = np.array([patch.get_y() for patch in patches])
        width = np.array([patch.get_height() for patch in patches])
    assert_array_equal(left, edges[:-1])
    assert_array_equal(left + width, edges[1:])


